     recurrence: actualEventRecurrence,\n        recurrences,\n        isAttendee,\n        selfAttendeeToken,\n    });\n    const {\n        multiSyncActions,\n        updatePartstatActions,\n        updatePersonalPartActions,\n        inviteActions: saveInviteActions,\n        sendActions,\n        hasStartChanged,\n    } = await getSaveRecurringEventActions({\n        type: saveType,\n        recurrences,\n        recurrence: actualEventRecurrence,\n        updateAllPossibilities,\n        newEditEventData,\n        oldEditEventData,\n        originalEditEventData,\n        inviteActions: updatedInviteActions,\n        hasDefaultNotifications,\n        personalEventsDeprecated,\n        isAttendee,\n        sendIcs,\n        reencryptSharedEvent,\n        selfAttendeeToken,\n    });\n    const successText = getRecurringEventUpdatedText(saveType, saveInviteActions);\n\n    return {\n        syncActions: multiSyncActions,\n        updatePartstatActions,\n        updatePersonalPartActions,\n        texts: { success: successText },\n        sendActions,\n        hasStartChanged,\n    };\n};\n\nexport default getSaveEventActions;\n","import { getDateOrDateTimeProperty } from '@proton/shared/lib/calendar/vcalConverter';\nimport { getHasDtend, getIsPropertyAllDay } from '@proton/shared/lib/calendar/vcalHelper';\nimport { addDays } from '@proton/shared/lib/date-fns-utc';\nimport { VcalVeventComponent } from '@proton/shared/lib/interfaces/calendar/VcalModel';\n\nimport { CalendarEventRecurring } from '../../../interfaces/CalendarEvents';\n\n// Merge the start and end of the occurrence into the dtstart and dtend of the original event component\nconst withOccurrenceEvent = (vevent: VcalVeventComponent, recurring: CalendarEventRecurring): VcalVeventComponent => {\n    const withOccurrenceDtstart = getDateOrDateTimeProperty(vevent.dtstart, recurring.localStart);\n    if (!getHasDtend(vevent)) {\n        return { ...vevent, dtstart: withOccurrenceDtstart };\n    }\n    // Add 