  oldModel: EventModel,\n    { start, end, isAllDay, tzid: fromTzid }: GetUpdateDateTimeArguments\n): EventModel => {\n    const tzStart = oldModel.start.tzid;\n    const tzEnd = oldModel.end.tzid;\n\n    // If there is a timezone, convert the fake UTC time in the timezone of the calendar to the specified timezone\n    const utcStart = tzStart !== fromTzid ? getTimeInTimezone(start, fromTzid, tzStart) : start;\n    const utcEnd = tzEnd !== fromTzid ? getTimeInTimezone(end, fromTzid, tzEnd) : end;\n    const newStart = getDateTimeState(utcStart, tzStart);\n    const newEnd = getDateTimeState(utcEnd, tzEnd);\n\n    return {\n        ...oldModel,\n        isAllDay,\n        start: newStart,\n        end: newEnd,\n        frequencyModel: getFrequencyModelChange(oldModel.start, newStart, oldModel.frequencyModel),\n    };\n};\n","import { CALENDAR_CARD_TYPE } from '@proton/shared/lib/calendar/constants';\nimport { unwrap } from '@proton/shared/lib/calendar/helper';\nimport { parse } from '@proton/shared/lib/calendar/vcal';\nimport { captureMessage } from '@proton/shared/lib/helpers/sentry';\nimport { CalendarEvent } from '@proton/shared/lib/interfaces/calendar';\n\nimport { SharedVcalVeventComponent } from '../interface';\n\nconst { CLEAR_TEXT, SIGNED } = CALENDAR_CARD_TYPE;\n\nconst getComponentFromCalendarEventUnencryptedPart = (eventData: CalendarEvent): SharedVcalVeventComponent => {\n    const unencryptedPart = eventData.SharedEvents.find(({ Type }) => [CLEAR_TEXT, SIGNED].includes(Type));\n    if (!unencryptedPart) {\n        throw new Error('Missing unencrypted part');\n    }\n    try {\n        return parse(unwrap(unencryptedPart.Data)) as SharedVcalVeventComponent;\n    } catch (e: any) {\n        /**\n         * We should always be able to parse events in the DB. If we can't that's bad, and we want to find out as soon as possible.\n         * For that we log the error to Sentry. The log includes the problematic ics card. It's ok to log it since it's not encrypted.\n         */\n        captureMessage('Unparseable clear part of calendar event', {\n            level: 'info',\n            extra: {\n                ics: unencryptedPart.Data,\n            },\n        });\n        if (e instanceof Error) {\n            throw e;\n        }\n        throw new Error('Unparseable unencrypted part of calendar event');\n    }\n};\n\nexport default getComponentFromCalendarEventUnencryptedPart;\n","import { getIsRecurring, getRecurrenceIdDate, getUidValue } from '@proton/shared/lib/calendar/vcalHelper';\nimport { APPS } from '@proton/shared/lib/constants';\nimport { postMessageFromIframe } from '@proton/shared/lib/drawer/helpers';\nimport { DRAWER_EVENTS } from '@proton/shared/lib/drawer/interfaces';\n\nimport { OpenedMailEvent } from '../../../../hooks/useGetOpenedMailEvents';\nimport { CalendarEventsCache } from '../interface';\nimport { removeEventFromRecurrenceInstances, removeEventFromRecurringCache } from './recurringCache';\n\nexport const removeCalendarEventStoreRecord = (\n    EventID: string,\n    { tree, events, recurringEvents }: CalendarEventsCache,\n    getOpenedMailEvents?: () => OpenedMailEvent[]\n) => {\n    const oldCalendarEventStoreRecord = events.get(EventID);\n    if (!oldCalendarEventStoreRecord) {\n        return;\n    }\n    const { utcStart, utcEnd, eventComponent } = oldCalendarEventStoreRecord;\n\n    tree.remove(+utcStart, +utcEnd, EventID);\n\n    const uid = getUidValue(eventComponent);\n    const recurrenceId = getRecurrenceIdDate(eventComponent);\n    const isRecurring = getIsRecurring(eventComponent);\n\n    if (recurrenceId) {\n        removeEventFromRecurrenceInstances(uid, +recurrenceId, recurringEvents, EventID);\n    } else if (isRecurring) {\n        removeEventFromRecurringCache(recurringEvents, uid, EventID);\n    }\n\n    events.delete(EventID);\n\n    // If the deleted event is open in Mail, tell it to refresh the widget\n    if ((getOpenedMailEvents?.() || []).find(({ UID }) => UID === uid)) 