   } = invitation;\n            const canonicalizedInvitedEmail = canonicalizeInternalEmail(invitedEmail);\n            const addressID = addresses.find(\n                ({ Email }) => canonicalizeInternalEmail(Email) === canonicalizedInvitedEmail\n            )?.ID;\n\n            try {\n                if (!addressID) {\n                    const text = 'Own address not found';\n                    createNotification({ type: 'error', text });\n                    throw new Error(text);\n                }\n                await acceptCalendarShareInvitation({\n                    addressID,\n                    calendarID,\n                    armoredPassphrase,\n                    getAddressKeys,\n                    api,\n                });\n                createNotification({\n                    type: 'success',\n                    text: c('Notification in shared calendar modal').t`Joined ${calendarName} (${senderEmail})`,\n                });\n                void call();\n            } catch {\n                noop();\n            } finally {\n                onFinish?.();\n            }\n        },\n        [api, getAddressKeys]\n    );\n\n    const reject = useCallback(\n        async (invitation: CalendarMemberInvitation, onFinish?: () => void) => {\n            const { CalendarID: calendarID, Email: invitedEmail } = invitation;\n            const canonicalizedInvitedEmail = canonicalizeInternalEmail(invitedEmail);\n            const addressID = addresses.find(\n                ({ Email }) => canonicalizeInternalEmail(Email) === canonicalizedInvitedEmail\n            )?.ID;\n\n            if (!addressID) {\n                const text = 'Own address not found';\n                createNotification({ type: 'error', text });\n                throw new Error(text);\n            }\n\n            try {\n                if (!addressID) {\n                    const text = 'Own address not found';\n                    createNotification({ type: 'error', text });\n                    throw new Error(text);\n                }\n                await rejectCalendarShareInvitation({ addressID, calendarID, api });\n                createNotification({\n                    type: 'success',\n                    text: c('Notification in shared calendar modal').t`Calendar invitation declined`,\n                });\n                void call();\n            } catch {\n                noop();\n            } finally {\n                onFinish?.();\n            }\n        },\n        [api]\n    );\n\n    return { accept, reject };\n};\n\nexport default useCalendarShareInvitationActions;\n","import { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport {\n    AlertModal,\n    ModalProps,\n    useCalendarShareInvitationActions,\n    useLoading,\n    useNotifications,\n    useSettingsLink,\n} from '@proton/components';\nimport CalendarLimitReachedModal from '@proton/components/containers/calendar/CalendarLimitReachedModal';\nimport { useContactEmailsCache } from '@proton/components/containers/contacts/ContactEmailsProvider';\nimport { CALENDAR_TYPE_EXTENDED } from '@proton/shared/lib/calendar/constants';\nimport getHasUserReachedCalendarsLimit from '@proton/shared/lib/calendar/getHasUserReachedCalendarsLimit';\nimport { APPS } from '@proton/shared/lib/constants';\nimport { getIsAddressDisabled } from '@proton/shared/lib/helpers/address';\nimport { canonicalizeInternalEmail } from '@proton/shared/lib/helpers/email';\nimport { Address, UserModel } from '@proton/shared/lib/interfaces';\nimport { CalendarMemberInvitation, VisualCalendar } from '@proton/shared/lib/interfaces/calendar';\n\nexport interface SharedCalendarModalOwnProps {\n    addresses: Address[];\n    calendars: VisualCalendar[];\n    user: UserModel;\n    invitation: CalendarMemberInvitation;\n}\n\ninterface Props extends ModalProps, SharedCalendarModalOwnProps {}\n\nconst ShareCalendarInvitationModal = ({ addresses, calendars, user, invitation, ...rest }: Props) => {\n    const { createNotification } = useNotifications();\n    const { contactEmailsMap } = useContactEmailsCache();\n    const goToSettings = useSettingsLink();\n    const [loadingAccept, withLoadingAccept] = useLoading();\n    const [loadingReject, withLoadingReject] = useLoading();\n    const { accept, reject } = useCalendarShareInvitationActions();\n\n    const canonicalizedInvitedEmail = canonicalizeInternalEmail(invitation.Email);\n    const invitedAddress = addresses.find(\n        ({ Email }) => canonicalizeInternalEmail(Email) === canonicalizedInvitedEmail\n    );\n\n    if (!invitedAddress) {\n        createNotification({\n            type: 'error',\n            text: c('Error accepting calendar invitation').t`Invited address does not exist`,\n        });\n        return null;\n    }\n\n    const calendarOwnerEmail = invitation.Calendar.SenderEmail;\n    const calendarName = invitation.Calendar.Name;\n    const isInvitedAddressDisabled = getIsAddressDisabled(invitedAddress);\n    const { isPersonalCalendarsLimitReached, isSharedCalendarsLimitReached } = getHasUserReachedCalendarsLimit({\n        calendars,\n        isFreeUser: !user.hasPaidMail,\n    });\n    const isCalendarsLimitReached = isPersonalCalendarsLimitReached || isSharedCalendarsLimitReached;\n\n    const handleAccept = () => withLoadingAccept(accept(invitation, rest.onClose));\n    const handleReject = () => withLoadingReject(reject(invitation, rest.onClose));\n    const handleGoToSettings = () => goToSettings('/identity-addresses', APPS.PROTONMAIL);\n\n    const calendarOwnerDisplayName = (\n        <span key=\"calendar-owner\" className=\"text-break\">\n            {contactEmailsMap[calendarOwnerEmail]?.Name || calendarOwnerEmail}\n        </span>\n    );\n    const boldCalendarName = (\n        <span key=\"bold-calendar-name\" className=\"text-bold text-break\">\n            {calendarName}\n        </span>\n    );\n    const boldCalendarOwnerEmail = (\n        <span key=\"bold-calendar-owner-email\" className=\"text-bold text-break\">\n            {calendarOwnerEmail}\n        </span>\n    );\n    const boldInvitedAddress = (\n        <span key=\"bold-invited-address\" className=\"text-bold text-break\">\n            {invitation.Email}\n        </span>\n    );\n\n    if (isCalendarsLimitReached && !isInvitedAddressDisabled) {\n        return <CalendarLimitReachedModal {...rest} calendarType={CALENDAR_TYPE_EXTENDED.SHARED} />;\n    }\n\n    const title = isInvitedAddressDisabled\n        ? c('Modal for received invitation to share calendar; Title').t`Unable to join more calendars`\n        : c('Modal for received invitation to share calendar; Title').t`Join calendar`;\n    const buttons: [JSX.Element, JSX.Element] = isInvitedAddressDisabled\n        ? [\n              <Button type=\"submit\" color=\"norm\" onClick={handleGoToSettings}>\n                  {c('Action').t`Manage addresses`}\n              </Button>,\n              <Button onClick={handleReject} loading={loadingReject}>\n                  {c('Action').t`Decline invite`}\n              </Button>,\n          ]\n        : [\n              <Button type=\"submit\" color=\"norm\" onClick={handleAccept} loading={loadingAccept}>\n                  {c('Action').t`Join calendar`}\n              </Button>,\n              <Button onClick={handleReject} loading={loadingReject}>\n                  {c('Action').t`No, thanks`}\n              </Button>,\n          ];\n\n    return (\n        <AlertModal {...rest} title={title} buttons={buttons}>\n            {isInvitedAddressDisabled ? (\n                <>\n                    <p>\n                        {c('Warning in modal to accept calendar invitation; Description')\n                            .jt`You cannot join this calendar because your invited email address (${boldInvitedAddress}) is disabled.`}\n                    </p>\n                    <p>\n                        {c('Warning in modal to accept calendar invitation; Description')\n                            .jt`To access this shared calendar, enable this address, or ask ${boldCalendarOwnerEmail} to send an invite to an active address.`}\n                    </p>\n                </>\n            ) : (\n                <p>\n                    {c('Modal for received invitation to share calendar; text')\n                        .jt`${calendarOwnerDisplayName} shared their calendar ${boldCalendarName} with you.`}\n                </p>\n            )}\n        </AlertModal>\n    );\n};\n\nexport default ShareCalendarInvitationModal;\n","import { getUnixTime } from 'date-fns';\n\nimport { queryEvents } from '@proton/shared/lib/api/calendars';\nimport { Api } from '@proton/shared/lib/interfaces';\nimport { CalendarEvent } from '@proton/shared/lib/interfaces/calendar';\nimport { CalendarEventsQueryType } from '@proton/shared/lib/interfaces/calendar/Api';\n\ninterface ApiResponse {\n    More: 0 | 1;\n    Events: CalendarEvent[];\n}\n\nconst PageSize = 100;\nconst QUERY_TYPES = [\n    CalendarEventsQueryType.PartDayInsideWindow,\n    CalendarEventsQueryType.PartDayBeforeWindow,\n    CalendarEventsQueryType.FullDayInsideWindow,\n    CalendarEventsQueryType.FullDayBeforeWindow,\n];\n\nconst getPaginatedEvents = async (\n    api: Api,\n    calendarID: string,\n    dateRange: Date[],\n    Timezone: string,\n    upsertEvent: (event: CalendarEvent) => void\n) => {\n    const params = {\n        // Special case, not using our boundaries, since the API does not accept negative values.\n        Start: Math.max(0, getUnixTime(dateRange[0])),\n        End: Math.max(0, getUnixTime(dateRange[1])),\n        Timezone,\n        PageSize,\n    };\n    const eventsOfType: CalendarEvent[][] = QUERY_TYPES.map(() => []);\n\n    async function* getEventsOfType({ Type }: { Type: CalendarEventsQueryType }) {\n        let More = 1;\n        let Page = 0;\n        let Events: CalendarEvent[] = [];\n        while (More === 1) {\n            ({ Events, More } = await api<ApiResponse>(queryEvents(calendarID, { ...params, Type, Page })));\n            Page += 1;\n            yield Events;\n        }\n    }\n\n    await Promise.all(\n        QUERY_TYPES.map(async (Type) => {\n            for await (const page of getEventsOfType({ Type })) {\n                eventsOfType[Type].push(...page);\n                for (const event of page) {\n                    upsertEvent(event);\n                }\n            }\n        })\n    );\n\n    return eventsOfType.flat();\n};\n\nexport default getPaginatedEvents;\n","import { generateProtonCalendarUID } from '@proton/shared/lib/calendar/helper';\nimport { Api } from '@proton/shared/lib/interfaces';\n\nimport { OpenedMailEvent } from '../../../../hooks/useGetOpenedMailEvents';\nimport getPaginatedEvents from '../getPaginatedEvents';\nimport { CalendarEventsCache } from '../interface';\nimport upsertCalendarApiEvent from './upsertCalendarApiEvent';\n\nconst getIsContained = (range: [Date, Date], otherRange: [Date, Date]) => {\n    return otherRange && +otherRange[1] >= +range[1] && +otherRange[0] <= +range[0];\n};\n\nexport const getExistingFetch = (dateRange: [Date, Date], { fetchTree, fetchCache }: CalendarEventsCache) => {\n    const existingFetches = fetchTree.search(+dateRange[0], +dateRange[1]).map(([, , id]) => fetchCache.get(id));\n\n    return existingFetches.find((otherFetch) => {\n        return otherFetch && getIsContained(dateRange, otherFetch.dateRange);\n    });\n};\n\nexport const fetchCalendarEvents = (\n    dateRange: [Date, Date],\n    calendarEventsCache: CalendarEventsCache,\n    api: Api,\n    calendarID: string,\n    tzid: string,\n    getOpenedMailEvents: () => OpenedMailEvent[],\n    noFetch: boolean\n) => {\n    const existingFetch = getExistingFetch(dateRange, calendarEventsCache);\n\n    const { fetchCache, fetchTree } = calendarEventsCache;\n\n    if (!existingFetch) {\n        const fetchId = generateProtonCalendarUID();\n        const getEventsPromise = noFetch\n            ? Promise.resolve([])\n            : getPaginatedEvents(api, calendarID, dateRange, tzid, (Event) =>\n                  upsertCalendarApiEvent(Event, calendarEventsCache, getOpenedMailEvents)\n              );\n        const promise = getEventsPromise\n            .then(() => {\n                if (fetchCache.get(fetchId)?.promise !== promise) {\n                    return;\n                }\n                fetchCache.set(fetchId, { dateRange });\n            })\n            .catch((error) => {\n                if (fetchCache.get(fetchId)?.promise !== promise) {\n                    throw error;\n                }\n                fetchTree.remove(+dateRange[0], +dateRange[1], fetchId);\n                fetchCache.delete(fetchId);\n                throw error;\n            });\n        fetchTree.insert(+dateRange[0], +dateRange[1], fetchId);\n        fetchCache.set(fetchId, { dateRange, promise });\n        return promise;\n    }\n\n    return existingFetch.promise;\n};\n","import createIntervalTree from '@protontech/interval-tree';\n\nimport { CalendarEventsCache } from '../interface';\n\nconst getCalendarEventsCache = (): CalendarEventsCache => {\n    return {\n        events: new Map(),\n        recurringEvents: new Map(),\n        tree: createIntervalTree(),\n        fetchCache: new Map(),\n        fetchUidCache: new Map(),\n        fetchTree: createIntervalTree(),\n    };\n};\n\nexport default getCalendarEventsCache;\n","import { MutableRefObject, useEffect, useState } from 'react';\n\nimport { useApi } from '@proton/components';\nimport { Calendar } from '@proton/shared/lib/interfaces/calendar';\nimport isTruthy from '@proton/utils/isTruthy';\n\nimport { OpenedMailEvent } from '../../../hooks/useGetOpenedMailEvents';\nimport { fetchCalendarEvents } from './cache/fetchCalendarEvents';\nimport getCalendarEventsCache from './cache/getCalendarEventsCache';\nimport { CalendarsEventsCache } from './interface';\n\nconst useCalendarsEventsFetcher = (\n    requestedCalendars: Calendar[],\n    utcDateRange: [Date, Date],\n    tzid: string,\n    cacheRef: MutableRefObject<CalendarsEventsCache>,\n    getOpenedMailEvents: () => OpenedMailEvent[],\n    initializeCacheOnlyCalendarsIDs: string[],\n    onCacheInitialized: () => void\n) => {\n    const [loading, setLoading] = useState(false);\n    const api = useApi();\n\n    useEffect(() => {\n        const calendarFetchPromises = requestedCalendars\n            .map(({ ID: CalendarID }) => {\n                let calendarEventsCache = cacheRef.current.calendars[CalendarID];\n                if (!calendarEventsCache) {\n                    calendarEventsCache = getCalendarEventsCache();\n                    cacheRef.current.calendars[CalendarID] = calendarEventsCache;\n                }\n                return fetchCalendarEvents(\n                    utcDateRange,\n                    calendarEventsCache,\n                    api,\n                    CalendarID,\n                    tzid,\n                    getOpenedMailEvents,\n                    initializeCacheOnlyCalendarsIDs.includes(CalendarID)\n                );\n            })\n            .filter(isTruthy);\n\n        if (calendarFetchPromises.length === 0) {\n            return setLoading(false);\n        }\n\n        let isActive = true;\n        setLoading(true);\n        const done = () => {\n            if (isActive) {\n                setLoading(false);\n                // even if some promise is rejected, consider cache initialized\n                onCacheInitialized();\n            }\n        };\n\n        Promise.all(calendarFetchPromises).then(done, done);\n\n        return () => {\n            isActive = false;\n        };\n    }, [requestedCalendars, utcDateRange]);\n\n    return loading;\n};\n\nexport default useCalendarsEventsFetcher;\n","import { MutableRefObject, useEffect, useRef, useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { useApi, useGetCalendarEventRaw } from '@proton/components';\nimport { getEvent as getEventRoute } from '@proton/shared/lib/api/calendars';\nimport { getApiWithAbort } from '@proton/shared/lib/api/helpers/customConfig';\nimport { naiveGetIsDecryptionError } from '@proton/shared/lib/calendar/helper';\nimport { pick } from '@proton/shared/lib/helpers/object';\nimport { wait } from '@proton/shared/lib/helpers/promise';\nimport { captureMessage } from '@proton/shared/lib/helpers/sentry';\nimport { Api, RequireSome } from '@proton/shared/lib/interfaces';\nimport { CalendarEvent } from '@proton/shared/lib/interfaces/calendar';\nimport { GetCalendarEventRaw } from '@proton/shared/lib/interfaces/hooks/GetCalendarEventRaw';\n\nimport { OpenedMailEvent } from '../../../hooks/useGetOpenedMailEvents';\nimport getAllEventsByUID from '../getAllEventsByUID';\nimport { CalendarViewEvent } from '../interface';\nimport { getIsCalendarEvent } from './cache/helper';\nimport upsertCalendarApiEvent from './cache/upsertCalendarApiEvent';\nimport {\n    CalendarEventStoreRecord,\n    CalendarEventsCache,\n    CalendarsEventsCache,\n    DecryptedEventTupleResult,\n    SharedVcalVeventComponent,\n    getEventStoreRecordHasEventData,\n} from './interface';\n\nconst SLOW_EVENT_BYPASS = {};\nconst EVENTS_PER_BATCH = 5;\nconst EVENTS_RACE_MS = 300;\n\nconst GET_EVENT_ERROR_MESSAGE = 'Failed to get event';\n\nconst getEventAndUpsert = async ({\n    calendarID,\n    eventID,\n    calendarEventsCache,\n    api,\n    getOpenedMailEvents,\n}: {\n    calendarID: string;\n    eventID: string;\n    calendarEventsCache: CalendarEventsCache;\n    api: Api;\n    getOpenedMailEvents?: () => OpenedMailEvent[];\n}): Promise<void> => {\n    try {\n        const { Event } = await api<{ Event: CalendarEvent }>({\n            ...getEventRoute(calendarID, eventID),\n            silence: true,\n        });\n        upsertCalendarApiEvent(Event, calendarEventsCache, getOpenedMailEvents);\n    } catch (error: any) {\n        throw new Error(GET_EVENT_ERROR_MESSAGE);\n    }\n};\n\nconst getDecryptedEvent = ({\n    calendarEvent,\n    getCalendarEventRaw,\n}: {\n    calendarEvent: CalendarEvent;\n    getCalendarEventRaw: GetCalendarEventRaw;\n}): Promise<DecryptedEventTupleResult> => {\n    return Promise.all([\n        getCalendarEventRaw(calendarEvent),\n        pick(calendarEvent, ['Permissions', 'IsOrganizer', 'IsProtonProtonInvite', 'IsPersonalMigrated']),\n    ]);\n};\n\n// Single edits are not always tied to the parent. Ensure that if the parent exists, it's in the cache before viewing it.\nconst getRecurringEventAndUpsert = ({\n    eventComponent,\n    calendarEvent,\n    cacheRef,\n    calendarEventsCache,\n    api,\n    getOpenedMailEvents,\n}: {\n    eventComponent: SharedVcalVeventComponent;\n    calendarEvent: CalendarEvent;\n    cacheRef: MutableRefObject<CalendarsEventsCache>;\n    calendarEventsCache: CalendarEventsCache;\n    api: Api;\n    getOpenedMailEvents?: () => OpenedMailEvent[];\n}): Promise<void> | undefined => {\n    if (!eventComponent['recurrence-id'] || !eventComponent.uid) {\n        return;\n    }\n\n    const cache = cacheRef.current;\n    const uid = eventComponent.uid.value;\n    const calendarID = calendarEvent.CalendarID;\n\n    const getParentEvent = () => {\n        const recurringEventsCache = cache.getCachedRecurringEvent(calendarID, uid);\n        const parentEventID = recurringEventsCache?.parentEventID;\n        if (!parentEventID) {\n            return;\n        }\n        return cache.getCachedEvent(calendarID, parentEventID);\n    };\n\n    if (getParentEvent()) {\n        return;\n    }\n\n    const oldFetchPromise = calendarEventsCache.fetchUidCache.get(uid);\n    if (oldFetchPromise?.promise) {\n        return oldFetchPromise.promise;\n    }\n\n    const newFetchPromise = getAllEventsByUID(api, calendarID, uid)\n        .then((eventOccurrences) => {\n            eventOccurrences.forEach((eventOccurrence) => {\n                upsertCalendarApiEvent(eventOccurrence, calendarEventsCache, getOpenedMailEvents);\n            });\n        })\n        .catch(() => {\n            calendarEventsCache.fetchUidCache.set(uid, { promise: undefined });\n            throw new Error(c('Error').t`Failed to get original occurrence in series`);\n        });\n    calendarEventsCache.fetchUidCache.set(uid, { promise: newFetchPromise });\n\n    return newFetchPromise;\n};\n\nconst setEventRecordPromise = ({\n    eventRecord,\n    getCalendarEventRaw,\n    cacheRef,\n    calendarEventsCache,\n    api,\n    getOpenedMailEvents,\n}: {\n    eventRecord: RequireSome<CalendarEventStoreRecord, 'eventData'>;\n    getCalendarEventRaw: GetCalendarEventRaw;\n    cacheRef: MutableRefObject<CalendarsEventsCache>;\n    calendarEventsCache: CalendarEventsCache;\n    api: Api;\n    getOpenedMailEvents?: () => OpenedMailEvent[];\n}) => {\n    const { eventData: calendarEvent, eventComponent } = eventRecord;\n\n    const onError = (error: any) => {\n        const errorMessage = error?.message || 'Unknown error';\n        if (!naiveGetIsDecryptionError(error)) {\n            /**\n             * (Temporarily) Log to Sentry any error not related to decryption\n             */\n            const { ID, CalendarID } = eventRecord.eventData || {};\n            captureMessage('Unexpected error reading calendar event', {\n                extra: { message: errorMessage, eventID: ID, calendarID: CalendarID },\n            });\n        }\n        eventRecord.eventReadResult = { error };\n        eventRecord.eventPromise = undefined;\n    };\n\n    if (!getIsCalendarEvent(calendarEvent)) {\n        const promise = getEventAndUpsert({\n            calendarID: calendarEvent.CalendarID,\n            eventID: calendarEvent.ID,\n            calendarEventsCache,\n            api,\n            getOpenedMailEvents,\n        })\n            .then(() => {\n                // getEventAndUpsert is already clearing these. Repeating here for safety\n                eventRecord.eventReadResult = undefined;\n                eventRecord.eventPromise = undefined;\n            })\n            .catch(onError);\n        eventRecord.eventPromise = promise;\n\n        return promise;\n    }\n\n    const promise = Promise.all([\n        getDecryptedEvent({\n            calendarEvent,\n            getCalendarEventRaw,\n        }),\n        getRecurringEventAndUpsert({\n            eventComponent: eventComponent,\n            calendarEvent,\n            cacheRef,\n            calendarEventsCache,\n            api,\n        }),\n    ])\n        .then(([eventDecrypted]) => {\n            return eventDecrypted;\n        })\n        .then((result) => {\n            eventRecord.eventReadResult = { result };\n            eventRecord.eventPromise = undefined;\n        })\n        .catch(onError);\n    eventRecord.eventPromise = promise;\n\n    return promise;\n};\n\nconst useCalendarsEventsReader = (\n    calendarEvents: CalendarViewEvent[],\n    cacheRef: MutableRefObject<CalendarsEventsCache>,\n    rerender: () => void,\n    getOpenedMailEvents: () => OpenedMailEvent[]\n) => {\n    const getCalendarEventRaw = useGetCalendarEventRaw();\n    const api = useApi();\n    const [loading, setLoading] = useState(false);\n    const abortControllerRef = useRef<AbortController>();\n\n    useEffect(() => {\n        const abortController = new AbortController();\n        abortControllerRef.current = abortController;\n        return () => {\n            abortController.abort();\n        };\n    }, []);\n\n    useEffect(() => {\n        const signal = abortControllerRef.current?.signal;\n        if (!signal) {\n            throw new Error('Required variables');\n        }\n        const apiWithAbort = getApiWithAbort(api, signal);\n\n        const seen = new Set();\n\n        const calendarEventPromises = calendarEvents.reduce<Promise<void>[]>((acc, calendarViewEvent) => {\n            if (acc.length === EVENTS_PER_BATCH) {\n                return acc;\n            }\n\n            const { calendarData, eventData } = calendarViewEvent.data;\n            const calendarEventsCache = cacheRef.current?.calendars[calendarData.ID];\n            const eventRecord = calendarEventsCache?.events.get(eventData?.ID || 'undefined');\n            if (!calendarEventsCache || !eventRecord || eventRecord.eventReadResult || seen.has(eventRecord)) {\n                return acc;\n            }\n\n            // To ignore recurring events\n            seen.add(eventRecord);\n\n            if (!getEventStoreRecordHasEventData(eventRecord)) {\n                eventRecord.eventReadResult = { error: new Error('Unknown process') };\n                return acc;\n            }\n\n            const getPromise = () =>\n                setEventRecordPromise({\n                    eventRecord,\n                    getCalendarEventRaw,\n                    cacheRef,\n                    calendarEventsCache,\n                    api: apiWithAbort,\n                    getOpenedMailEvents,\n                });\n\n            if (!eventRecord.eventReadRetry) {\n                eventRecord.eventReadRetry = () => getPromise().then(rerender);\n            }\n\n            if (!eventRecord.eventPromise) {\n                acc.push(getPromise());\n            }\n\n            return acc;\n        }, []);\n\n        if (calendarEventPromises.length === 0) {\n            return setLoading(false);\n        }\n\n        let isActive = true;\n        setLoading(true);\n        const done = () => {\n            if (isActive) {\n                setLoading(false);\n                rerender();\n            }\n        };\n\n        const run = async () => {\n            const allCalendarEventPromise = Promise.all(calendarEventPromises);\n\n            // The first one to complete. It's mostly intended to avoid api event fetches blocking other actions.\n            const raceResult = await Promise.race([\n                allCalendarEventPromise,\n                wait(EVENTS_RACE_MS).then(() => SLOW_EVENT_BYPASS),\n            ]);\n\n            // If the slow event bypass won, set up a handler for when all the events have finished (in case a re-render never happens)\n            if (raceResult === SLOW_EVENT_BYPASS) {\n                allCalendarEventPromise.then(done, done);\n            } else {\n                done();\n            }\n        };\n\n        run().catch(done);\n\n        return () => {\n            isActive = false;\n        };\n    }, [calendarEvents]);\n\n    return loading;\n};\n\nexport default useCalendarsEventsReader;\n","import createIntervalTree from '@protontech/interval-tree';\n\nimport { SHARED_SIGNED_FIELDS } from '@proton/shared/lib/calendar/constants';\nimport { OccurrenceIterationCache } from '@proton/shared/lib/calendar/recurrence/recurring';\nimport { pick } from '@proton/shared/lib/helpers/object';\nimport { RequireSome } from '@proton/shared/lib/interfaces';\nimport { CalendarEvent, CalendarEventSharedData, DecryptedVeventResult } from '@proton/shared/lib/interfaces/calendar';\nimport { VcalVeventComponent } from '@proton/shared/lib/interfaces/calendar/VcalModel';\n\nimport { EventInternalProperties } from '../../../interfaces/EventInternalProperties';\n\nexport type IntervalTree = ReturnType<typeof createIntervalTree>;\n\nexport interface RecurringCache {\n    parentEventID?: string;\n    cache?: Partial<OccurrenceIterationCache>;\n    recurrenceInstances?: { [key: number]: string };\n}\n\nexport type DecryptedEventTupleResult = [\n    DecryptedVeventResult,\n    Pick<EventInternalProperties, 'Permissions' | 'IsProtonProtonInvite' | 'IsPersonalMigrated'>\n];\nexport type EventReadResult = {\n    result?: DecryptedEventTupleResult;\n    error?: Error;\n};\n\n// Just to get picked types\nconst sharedPick = (x: VcalVeventComponent) => pick(x, [...SHARED_SIGNED_FIELDS, 'component']);\nexport type SharedVcalVeventComponent = ReturnType<typeof sharedPick>;\nexport type MetadataVcalVeventComponent = Pick<\n    VcalVeventComponent,\n    'uid' | 'dtstamp' | 'component' | 'dtstart' | 'dtend' | 'recurrence-id' | 'exdate' | 'rrule'\n>;\n\nexport interface CalendarEventStoreRecord {\n    utcStart: Date;\n    utcEnd: Date;\n\n    isAllDay: boolean;\n    isAllPartDay: boolean;\n\n    eventData?: CalendarEvent | CalendarEventSharedData;\n    eventComponent: SharedVcalVeventComponent | MetadataVcalVeventComponent;\n    eventReadResult?: EventReadResult;\n    eventPromise?: Promise<void>;\n    eventReadRetry?: () => Promise<void>;\n}\n\nexport const getEventStoreRecordHasEventData = (\n    record: CalendarEventStoreRecord\n): record is RequireSome<CalendarEventStoreRecord, 'eventData'> => {\n    return !!record.eventData;\n};\n\nexport type RecurringEventsCache = Map<string, RecurringCache>;\nexport type EventsCache = Map<string, CalendarEventStoreRecord>;\nexport type FetchCache = Map<string, { promise?: Promise<void>; dateRange: [Date, Date] }>;\nexport type FetchUidCache = Map<string, { promise?: Promise<void> }>;\nexport interface CalendarEventsCache {\n    events: EventsCache;\n    recurringEvents: RecurringEventsCache;\n    tree: IntervalTree;\n    fetchTree: IntervalTree;\n    fetchCache: FetchCache;\n    fetchUidCache: FetchUidCache;\n}\n\nexport interface CalendarsEventsCache {\n    ref: number;\n    isUnmounted: boolean;\n    calendars: {\n        [key: string]: CalendarEventsCache | undefined;\n    };\n    getCachedEvent: (calendarID: string, eventID: string) => CalendarEvent | undefined;\n    getCachedRecurringEvent: (calendarID: string, uid: string) => RecurringCache | undefined;\n    retryReadEvent: (calendarID: string, eventID: string) => Promise<void>;\n    rerender?: () => void;\n}\n\nexport type GetDecryptedEventCb = (Event: CalendarEvent) => Promise<DecryptedEventTupleResult>;\n","import { MutableRefObject, useEffect, useMemo, useState } from 'react';\n\nimport { getIsAutoAddedInvite } from '@proton/shared/lib/calendar/apiModels';\nimport { getIsOwnedCalendar } from '@proton/shared/lib/calendar/calendar';\nimport { DAY } from '@proton/shared/lib/constants';\nimport { fromUTCDateToLocalFakeUTCDate } from '@proton/shared/lib/date/timezone';\nimport { VisualCalendar } from '@proton/shared/lib/interfaces/calendar';\nimport isTruthy from '@proton/utils/isTruthy';\n\nimport { OpenedMailEvent } from '../../../hooks/useGetOpenedMailEvents';\nimport { CalendarViewEvent, CalendarViewEventData } from '../interface';\nimport { getExistingFetch } from './cache/fetchCalendarEvents';\nimport { getRecurringEvents } from './cache/getRecurringEvents';\nimport { getIsCalendarEvent } from './cache/helper';\nimport { CalendarsEventsCache } from './interface';\nimport useCalendarsEventsFetcher from './useCalendarsEventsFetcher';\nimport useCalendarsEventsReader from './useCalendarsEventsReader';\n\nconst useCalendarsEvents = (\n    requestedCalendars: VisualCalendar[],\n    utcDateRange: [Date, Date],\n    tzid: string,\n    cacheRef: MutableRefObject<CalendarsEventsCache>,\n    getOpenedMailEvents: () => OpenedMailEvent[],\n    initializeCacheOnlyCalendarsIDs: string[],\n    onCacheInitialized: () => void\n): [CalendarViewEvent[], boolean] => {\n    const [rerender, setRerender] = useState<any>();\n    const loading = useCalendarsEventsFetcher(\n        requestedCalendars,\n        utcDateRange,\n        tzid,\n        cacheRef,\n        getOpenedMailEvents,\n        initializeCacheOnlyCalendarsIDs,\n        onCacheInitialized\n    );\n\n    useEffect(() => {\n        let isActive = true;\n        cacheRef.current.rerender = () => {\n            if (isActive) {\n                setRerender({});\n            }\n        };\n        return () => {\n            cacheRef.current.rerender = undefined;\n            isActive = false;\n        };\n    }, []);\n\n    const eventsResults = useMemo((): CalendarViewEvent[] => {\n        return requestedCalendars\n            .map((calendar) => {\n                const isOwnedCalendar = getIsOwnedCalendar(calendar);\n                const calendarEventsCache = cacheRef.current?.calendars[calendar.ID];\n                if (!calendarEventsCache) {\n                    return [];\n                }\n\n                // If this date range is not contained in the result, we don't return anything because we can't trust the recurring events\n                // until we have complete data fetched for this range because of single editions\n                const existingFetch = getExistingFetch(utcDateRange, calendarEventsCache);\n                if (!existingFetch || existingFetch.promise) {\n                    return [];\n                }\n\n                // Add a day in both ranges to not miss events due to tz since they are stored in UTC time\n                const searchStart = +utcDateRange[0] - DAY;\n                const searchEnd = +utcDateRange[1] + DAY;\n\n                const results = calendarEventsCache.tree\n                    .search(searchStart, searchEnd)\n                    .map(([, , id]): CalendarViewEvent | undefined => {\n                        const cachedRecord = calendarEventsCache.events.get(id);\n                        if (!cachedRecord) {\n                            return;\n                        }\n                        const { utcStart, utcEnd, eventData, isAllDay, isAllPartDay, eventReadResult } = cachedRecord;\n\n                        const data: CalendarViewEventData = {\n                            eventData,\n                            eventReadResult,\n                            calendarData: calendar,\n                        };\n                        const isAutoAddedInvite = !!(\n                            eventData &&\n                            getIsCalendarEvent(eventData) &&\n                            getIsAutoAddedInvite(eventData)\n                        );\n\n                        if (isAutoAddedInvite && !isOwnedCalendar) {\n                            // ignore auto-added invites in shared calendars (they can't be decrypted)\n                            return;\n                        }\n\n                        return {\n                            id,\n                            isAllDay,\n                            isAllPartDay,\n                            start: utcStart,\n                            end: utcEnd,\n                            data,\n                        };\n                    })\n                    .filter(isTruthy);\n\n                const recurringResults = getRecurringEvents(\n                    calendarEventsCache.events,\n                    calendarEventsCache.recurringEvents,\n                    searchStart,\n                    searchEnd\n                )\n                    .map(({ id, eventOccurrences, isSingleOccurrence }) => {\n                        const cachedRecord = calendarEventsCache.events.get(id);\n                        if (!cachedRecord) {\n                            return [];\n                        }\n                        const { eventData, isAllDay, isAllPartDay, eventReadResult } = cachedRecord;\n\n                        const data: CalendarViewEventData = {\n                            eventData,\n                            eventReadResult,\n                            calendarData: calendar,\n                        };\n                        const isAutoAddedInvite = !!(\n                            eventData &&\n                            getIsCalendarEvent(eventData) &&\n                            getIsAutoAddedInvite(eventData)\n                        );\n\n                        if (isAutoAddedInvite && !isOwnedCalendar) {\n                            // ignore auto-added invites in shared calendars (they can't be decrypted)\n                            return;\n                        }\n\n                        return eventOccurrences.map(\n                            ({ utcStart, utcEnd, localStart, localEnd, occurrenceNumber }): CalendarViewEvent => {\n                                const recurrence = {\n                                    occurrenceNumber,\n                                    localStart,\n                                    localEnd,\n                                    isSingleOccurrence,\n                                };\n                                return {\n                                    id: `${id}-${occurrenceNumber}`,\n                                    isAllDay,\n                                    isAllPartDay,\n                                    start: utcStart,\n                                    end: utcEnd,\n                                    data: {\n                                        ...data,\n                                        eventRecurrence: recurrence,\n                                    },\n                                };\n                            }\n                        );\n                    })\n                    .filter(isTruthy)\n                    .flat(1);\n\n                return results\n                    .concat(recurringResults)\n                    .map(({ start: utcStart, end: utcEnd, isAllDay, isAllPartDay, data, id }): CalendarViewEvent => {\n                        const start = fromUTCDateToLocalFakeUTCDate(utcStart, isAllDay, tzid);\n                        const end = fromUTCDateToLocalFakeUTCDate(utcEnd, isAllDay, tzid);\n\n                        return {\n                            id,\n                            isAllDay: isAllDay || isAllPartDay,\n                            isAllPartDay,\n                            start,\n                            end,\n                            data,\n                        };\n                    });\n            })\n            .flat();\n    }, [rerender, loading, tzid, requestedCalendars, utcDateRange]);\n\n    useCalendarsEventsReader(eventsResults, cacheRef, () => setRerender({}), getOpenedMailEvents);\n\n    return [eventsResults, loading];\n};\n\nexport default useCalendarsEvents;\n","import {\n    RecurringResult,\n    getOccurrences,\n    getOccurrencesBetween,\n} from '@proton/shared/lib/calendar/recurrence/recurring';\n\nimport { EventsCache, RecurringEventsCache } from '../interface';\n\ninterface Result {\n    id: string;\n    eventOccurrences: RecurringResult[];\n    isSingleOccurrence: boolean;\n}\n\nexport const getRecurringEvents = (\n    events: EventsCache,\n    recurringEvents: RecurringEventsCache,\n    searchStart: number,\n    searchEnd: number\n) => {\n    const result: Result[] = [];\n\n    for (const uid of recurringEvents.keys()) {\n        const recurringEventsCacheRecord = recurringEvents.get(uid);\n        if (!recurringEventsCacheRecord) {\n            continue;\n        }\n        const { parentEventID, recurrenceInstances, cache } = recurringEventsCacheRecord;\n\n        // If just a recurrence-id was received, without a link to any parent\n        if (!parentEventID) {\n            continue;\n        }\n\n        const parentEventCacheRecord = events.get(parentEventID);\n        if (!parentEventCacheRecord) {\n            continue;\n        }\n\n        const { eventComponent } = parentEventCacheRecord;\n\n        let eventOccurrences = getOccurrencesBetween(eventComponent, searchStart, searchEnd, cache);\n        if (!eventOccurrences.length) {\n            continue;\n        }\n\n        if (recurrenceInstances) {\n            // Remove the individual recurrence instances from the occurrences\n            eventOccurrences = eventOccurrences.filter((occurrence) => {\n                const { localStart } = occurrence;\n                return !recurrenceInstances[+localStart];\n            });\n        }\n\n        const isSingleOccurrence = getOccurrences({ component: eventComponent, maxCount: 2, cache }).length === 1;\n\n        result.push({\n            id: parentEventID,\n            eventOccurrences,\n            isSingleOccurrence,\n        });\n    }\n\n    return result;\n};\n","import { VIEWS } from '@proton/shared/lib/calendar/constants';\nimport {\n    addDays,\n    addWeeks,\n    endOfDay,\n    endOfMonth,\n    endOfWeek,\n    endOfYear,\n    startOfDay,\n    startOfMonth,\n    startOfWeek,\n    startOfYear,\n} from '@proton/shared/lib/date-fns-utc';\nimport { WeekStartsOn } from '@proton/shared/lib/date-fns-utc/interface';\n\nconst getDateRange = (date: Date, range: number | undefined, view: VIEWS, weekStartsOn: WeekStartsOn): [Date, Date] => {\n    const opts = { weekStartsOn };\n    switch (view) {\n        case VIEWS.DAY:\n            return [startOfDay(date), endOfDay(date)];\n        case VIEWS.WEEK:\n            if (range && range > 0) {\n                return [startOfDay(date), endOfDay(addDays(date, range))];\n            }\n            return [startOfWeek(date, opts), endOfWeek(date, opts)];\n        case VIEWS.MONTH:\n            if (range && range > 0) {\n                return [startOfWeek(date, opts), endOfWeek(addWeeks(date, range), opts)];\n            }\n            return [startOfWeek(startOfMonth(date), opts), endOfWeek(endOfMonth(date), opts)];\n        case VIEWS.YEAR:\n            return [startOfWeek(startOfYear(date), opts), endOfWeek(endOfYear(date), opts)];\n        case VIEWS.AGENDA:\n            return [startOfDay(date), addDays(startOfDay(date), 30)];\n        default:\n            return [startOfWeek(date, opts), endOfWeek(date, opts)];\n    }\n};\n\nexport default getDateRange;\n","import { VIEWS } from '@proton/shared/lib/calendar/constants';\nimport { format } from '@proton/shared/lib/date-fns-utc';\nimport { dateLocale } from '@proton/shared/lib/i18n';\n\nconst getTitleDateString = (view: VIEWS, range: number | undefined, utcDateRange: Date[], utcDate: Date) => {\n    const formatOptions = { locale: dateLocale };\n\n    if (view === VIEWS.DAY) {\n        return format(utcDate, 'PPPP', formatOptions);\n    }\n\n    if (view === VIEWS.WEEK || (range && range > 0)) {\n        const [utcFrom, utcTo] = utcDateRange;\n\n        if (utcFrom.getUTCMonth() === utcTo.getUTCMonth()) {\n            const fromString = format(utcFrom, 'd', formatOptions);\n            const toString = format(utcTo, 'd', formatOptions);\n            const rest = format(utcDate, 'MMMM yyyy', formatOptions);\n            return `${fromString}-${toString} ${rest}`;\n        }\n\n        if (utcFrom.getUTCFullYear() === utcTo.getUTCFullYear()) {\n            const fromString = format(utcFrom, 'd MMMM', formatOptions);\n            const toString = format(utcTo, 'd MMMM', formatOptions);\n            const rest = format(utcFrom, 'yyyy', formatOptions);\n            return `${fromString} - ${toString} ${rest}`;\n        }\n\n        const fromString = format(utcFrom, 'd MMMM yyyy', formatOptions);\n        const toString = format(utcTo, 'd MMMM yyyy', formatOptions);\n        return `${fromString} - ${toString}`;\n    }\n\n    return format(utcDate, 'LLLL yyyy', formatOptions);\n};\n\nexport default getTitleDateString;\n","import { MutableRefObject, useCallback, useEffect, useMemo, useReducer, useRef, useState } from 'react';\nimport { useHistory, useLocation } from 'react-router-dom';\n\nimport { c } from 'ttag';\n\nimport { useApi, useAppTitle, useCalendarBootstrap, useModalState, useNotifications } from '@proton/components';\nimport { getInvitation } from '@proton/shared/lib/api/calendars';\nimport { getIsCalendarWritable } from '@proton/shared/lib/calendar/calendar';\nimport { MAXIMUM_DATE_UTC, MINIMUM_DATE_UTC, VIEWS } from '@proton/shared/lib/calendar/constants';\nimport {\n    getAutoDetectPrimaryTimezone,\n    getDefaultTzid,\n    getDefaultView,\n    getDisplaySecondaryTimezone,\n    getDisplayWeekNumbers,\n    getInviteLocale,\n    getSecondaryTimezone,\n} from '@proton/shared/lib/calendar/getSettings';\nimport { SECOND } from '@proton/shared/lib/constants';\nimport { MILLISECONDS_IN_MINUTE, isSameDay } from '@proton/shared/lib/date-fns-utc';\nimport {\n    convertUTCDateTimeToZone,\n    convertZonedDateTimeToUTC,\n    formatGMTOffsetAbbreviation,\n    fromUTCDate,\n    getIsEquivalentTimeZone,\n    getTimezone,\n    getTimezoneOffset,\n    toUTCDate,\n} from '@proton/shared/lib/date/timezone';\nimport { Address, UserModel, UserSettings } from '@proton/shared/lib/interfaces';\nimport {\n    AttendeeModel,\n    CalendarMemberInvitation,\n    CalendarUserSettings,\n    MEMBER_INVITATION_STATUS,\n    VisualCalendar,\n} from '@proton/shared/lib/interfaces/calendar';\nimport { getWeekStartsOn } from '@proton/shared/lib/settings/helper';\nimport unary from '@proton/utils/unary';\n\nimport { getNoonDateForTimeZoneOffset } from '../../helpers/date';\nimport {\n    canAskTimezoneSuggestion,\n    getTimezoneSuggestionKey,\n    saveLastTimezoneSuggestion,\n} from '../../helpers/timezoneSuggestion';\nimport { OpenedMailEvent } from '../../hooks/useGetOpenedMailEvents';\nimport AskUpdateTimezoneModal from '../settings/AskUpdateTimezoneModal';\nimport CalendarContainerView from './CalendarContainerView';\nimport InteractiveCalendarView from './InteractiveCalendarView';\nimport ShareCalendarInvitationModal from './ShareCalendarInvitationModal';\nimport { SUPPORTED_VIEWS_IN_APP, SUPPORTED_VIEWS_IN_DRAWER } from './constants';\nimport { CalendarsEventsCache } from './eventStore/interface';\nimport useCalendarsEvents from './eventStore/useCalendarsEvents';\nimport getDateRange from './getDateRange';\nimport getTitleDateString from './getTitleDateString';\nimport { fromUrlParams, toUrlParams } from './getUrlHelper';\nimport { EventTargetAction, InteractiveRef, TimeGridRef } from './interface';\n\nconst { DAY, WEEK, MONTH } = VIEWS;\n\nconst getRange = (view: VIEWS, range: number) => {\n    if (!range) {\n        return;\n    }\n    const max = Math.max(Math.min(range, 6), 1);\n    if (view === WEEK) {\n        return max;\n    }\n    return Math.min(max, 5);\n};\n\nconst customReducer = (oldState: { [key: string]: any }, newState: { [key: string]: any }) => {\n    const keys = Object.keys(newState);\n    for (const key of keys) {\n        // If there is a difference in any of the keys, return a new object.\n        if (oldState[key] !== newState[key]) {\n            return {\n                ...oldState,\n                ...newState,\n            };\n        }\n    }\n    // Otherwise return the old state to prevent a re-render\n    return oldState;\n};\n\ninterface Props {\n    tzid: string;\n    setCustomTzid: (tzid: string) => void;\n    isNarrow: boolean;\n    drawerView?: VIEWS;\n    user: UserModel;\n    addresses: Address[];\n    activeAddresses: Address[];\n    visibleCalendars: VisualCalendar[];\n    activeCalendars: VisualCalendar[];\n    calendars: VisualCalendar[];\n    defaultCalendar?: VisualCalendar;\n    userSettings: UserSettings;\n    calendarUserSettings: CalendarUserSettings;\n    calendarsEventsCacheRef: MutableRefObject<CalendarsEventsCache>;\n    eventTargetActionRef: MutableRefObject<EventTargetAction | undefined>;\n    shareCalendarInvitationRef: MutableRefObject<{ calendarID: string; invitationID: string } | undefined>;\n    startupModalState: { hasModal?: boolean; isOpen: boolean };\n    getOpenedMailEvents: () => OpenedMailEvent[];\n}\n\nconst CalendarContainer = ({\n    tzid,\n    setCustomTzid,\n    isNarrow,\n    drawerView,\n    user,\n    addresses,\n    activeAddresses,\n    calendars,\n    activeCalendars,\n    visibleCalendars,\n    defaultCalendar,\n    userSettings,\n    calendarUserSettings,\n    calendarsEventsCacheRef,\n    eventTargetActionRef,\n    shareCalendarInvitationRef,\n    startupModalState,\n    getOpenedMailEvents,\n}: Props) => {\n    const history = useHistory();\n    const location = useLocation();\n    const api = useApi();\n    const { createNotification } = useNotifications();\n    const [disableCreate, setDisableCreate] = useState(false);\n    const [shareCalendarInvitation, setShareCalendarInvitation] = useState<CalendarMemberInvitation>();\n    const [isAskUpdateTimezoneModalOpen, setIsAskUpdateTimezoneModalOpen] = useState(false);\n    const [shareCalendarInvitationModal, setIsSharedCalendarInvitationModalOpen, renderShareCalendarInvitationModal] =\n        useModalState();\n\n    const interactiveRef = useRef<InteractiveRef>(null);\n    const timeGridViewRef = useRef<TimeGridRef>(null);\n\n    const [nowDate, setNowDate] = useState(() => new Date());\n    const [localTimezoneId, setLocalTimezoneId] = useState<string>();\n\n    useEffect(() => {\n        const handle = setInterval(() => setNowDate(new Date()), 30 * SECOND);\n        return () => {\n            clearInterval(handle);\n        };\n    }, []);\n\n    useEffect(() => {\n        return () => {\n            setCustomTzid('');\n        };\n    }, []);\n\n    const {\n        view: urlView,\n        range: urlRange,\n        date: urlDate,\n    } = useMemo(() => fromUrlParams(location.pathname), [location.pathname]);\n\n    // In the same to get around setStates not being batched in the range selector callback.\n    const [{ view: customView, range: customRange, date: customUtcDate }, setCustom] = useReducer(\n        customReducer,\n        undefined,\n        () => {\n            return { view: urlView, range: urlRange, date: urlDate };\n        }\n    );\n\n    useEffect(() => {\n        // We only care about new dates in the URL when the browser moves back or forward, not from push states coming from the app.\n        if (history.action === 'POP') {\n            setCustom({ view: urlView, range: urlRange, date: urlDate });\n        }\n    }, [urlDate, urlView, urlRange]);\n\n    useEffect(() => {\n        const run = async () => {\n            if (startupModalState.hasModal === undefined || startupModalState.isOpen) {\n                return;\n            }\n            let doNotShowAskTimezoneUpdateModal =\n                !!shareCalendarInvitationRef.current ||\n                drawerView ||\n                !getAutoDetectPrimaryTimezone(calendarUserSettings);\n            if (shareCalendarInvitationRef.current) {\n                try {\n                    const { calendarID, invitationID } = shareCalendarInvitationRef.current;\n                    const { Invitation } = await api<{ Code: number; Invitation: CalendarMemberInvitation }>(\n                        getInvitation(calendarID, invitationID)\n                    );\n                    if (Invitation.Status === MEMBER_INVITATION_STATUS.ACCEPTED) {\n                        createNotification({\n                            type: 'success',\n                            text: c('Info').t`You already joined this calendar`,\n                        });\n                    } else if (Invitation.Status === MEMBER_INVITATION_STATUS.REJECTED) {\n                        createNotification({\n                            type: 'error',\n                            text: c('Info').t`You previously rejected this invitation. Ask the owner for a re-invite`,\n                        });\n                    } else {\n                        setShareCalendarInvitation(Invitation);\n                        setIsSharedCalendarInvitationModalOpen(true);\n                    }\n                } catch (e) {\n                    console.error(e);\n                }\n            }\n\n            if (doNotShowAskTimezoneUpdateModal) {\n                return;\n            }\n\n            const localTzid = getTimezone();\n            const savedTzid = getDefaultTzid(calendarUserSettings, localTzid);\n            const key = await getTimezoneSuggestionKey(user.ID);\n            if (!getIsEquivalentTimeZone(localTzid, savedTzid) && canAskTimezoneSuggestion(key)) {\n                saveLastTimezoneSuggestion(key);\n                setIsAskUpdateTimezoneModalOpen(true);\n                setLocalTimezoneId(localTzid);\n            }\n        };\n        void run();\n    }, [startupModalState]);\n\n    const utcNowDateInTimezone = useMemo(() => {\n        return toUTCDate(convertUTCDateTimeToZone(fromUTCDate(nowDate), tzid));\n    }, [nowDate, tzid]);\n\n    const utcDefaultDateRef = useRef<{ prev: Date; value: Date }>();\n    // A ref is used to avoid falling on the cache purging of react\n    if (\n        !utcDefaultDateRef.current ||\n        (utcDefaultDateRef.current.prev !== utcNowDateInTimezone &&\n            !isSameDay(utcDefaultDateRef.current.value, utcNowDateInTimezone))\n    ) {\n        utcDefaultDateRef.current = {\n            prev: utcNowDateInTimezone,\n            value: new Date(\n                Date.UTC(\n                    utcNowDateInTimezone.getUTCFullYear(),\n                    utcNowDateInTimezone.getUTCMonth(),\n                    utcNowDateInTimezone.getUTCDate()\n                )\n            ),\n        };\n    }\n    const utcDefaultDate = utcDefaultDateRef.current.value;\n\n    const utcDate = customUtcDate || utcDefaultDate;\n\n    const defaultView = getDefaultView(calendarUserSettings);\n    const requestedView = customView || defaultView;\n    const view = (() => {\n        if (SUPPORTED_VIEWS_IN_DRAWER.includes(requestedView)) {\n            return requestedView;\n        }\n        if (isNarrow) {\n            return WEEK;\n        }\n\n        if (SUPPORTED_VIEWS_IN_APP.includes(requestedView)) {\n            return requestedView;\n        }\n\n        return WEEK;\n    })();\n\n    const range = isNarrow ? undefined : getRange(view, customRange);\n    const weekStartsOn = getWeekStartsOn(userSettings);\n    const displayWeekNumbers = getDisplayWeekNumbers(calendarUserSettings);\n    const displaySecondaryTimezone = getDisplaySecondaryTimezone(calendarUserSettings);\n    const secondaryTzid = getSecondaryTimezone(calendarUserSettings);\n    const inviteLocale = getInviteLocale(calendarUserSettings);\n\n    const utcDateRange = useMemo(() => {\n        return getDateRange(utcDate, range, view, weekStartsOn);\n    }, [view, utcDate, weekStartsOn, range]);\n\n    const utcDateRangeInTimezone = useMemo(\n        (): [Date, Date] => [\n            toUTCDate(convertZonedDateTimeToUTC(fromUTCDate(utcDateRange[0]), tzid)),\n            toUTCDate(convertZonedDateTimeToUTC(fromUTCDate(utcDateRange[1]), tzid)),\n        ],\n        [utcDateRange, tzid]\n    );\n\n    const timezoneInformation = useMemo(() => {\n        // in responsive mode we display just one day even though the view is WEEK\n        const startDate = isNarrow ? utcDate : utcDateRangeInTimezone[0];\n        const noonDate = getNoonDateForTimeZoneOffset(startDate);\n        const { offset } = getTimezoneOffset(noonDate, tzid);\n        const { offset: secondaryOffset } = getTimezoneOffset(noonDate, secondaryTzid || tzid);\n        return {\n            primaryTimezone: `${formatGMTOffsetAbbreviation(offset)}`,\n            secondaryTimezone: `${formatGMTOffsetAbbreviation(secondaryOffset)}`,\n            secondaryTimezoneOffset: (secondaryOffset - offset) * MILLISECONDS_IN_MINUTE,\n        };\n    }, [utcDate, utcDateRangeInTimezone, secondaryTzid, tzid, isNarrow]);\n\n    useEffect(() => {\n        const newRoute = toUrlParams({\n            date: utcDate,\n            defaultDate: utcDefaultDate,\n            view,\n            defaultView,\n            range,\n        });\n        if (location.pathname === newRoute) {\n            return;\n        }\n        history.push({ pathname: newRoute });\n        // Intentionally not listening to everything to only trigger URL updates when these variables change.\n    }, [view, range, utcDate]);\n\n    const calendarTitle = useMemo(() => {\n        return getTitleDateString(view, range, utcDateRange, utcDate);\n    }, [view, range, utcDate, utcDateRange]);\n\n    useAppTitle(calendarTitle);\n\n    const [initializeCacheOnlyCalendarsIDs, setInitializeCacheOnlyCalendarsIDs] = useState<string[]>([]);\n    const [calendarsEvents, loadingEvents] = useCalendarsEvents(\n        visibleCalendars,\n        utcDateRangeInTimezone,\n        tzid,\n        calendarsEventsCacheRef,\n        getOpenedMailEvents,\n        initializeCacheOnlyCalendarsIDs,\n        () => setInitializeCacheOnlyCalendarsIDs([])\n    );\n\n    const scrollToNow = useCallback(() => {\n        setTimeout(() => {\n            timeGridViewRef.current?.scrollToNow?.();\n        }, 10);\n    }, []);\n\n    const handleChangeView = useCallback((newView: VIEWS) => {\n        setCustom({ view: newView, range: undefined });\n        scrollToNow();\n    }, []);\n\n    const handleClickToday = useCallback(() => {\n        utcDefaultDateRef.current = undefined; // Purpose: Reset the minicalendar when clicking today multiple times\n        setCustom({ date: utcDefaultDate, range: undefined });\n        scrollToNow();\n    }, [utcDefaultDate]);\n\n    const handleChangeDate = useCallback((newDate: Date) => {\n        if (newDate < MINIMUM_DATE_UTC || newDate > MAXIMUM_DATE_UTC) {\n            return;\n        }\n        setCustom({ date: newDate });\n    }, []);\n\n    const handleChangeDateRange = useCallback((newDate: Date, numberOfDays: number, resetRange?: boolean) => {\n        if (newDate < MINIMUM_DATE_UTC || newDate > MAXIMUM_DATE_UTC) {\n            return;\n        }\n        if (numberOfDays >= 7) {\n            setCustom({\n                view: MONTH,\n                range: Math.floor(numberOfDays / 7),\n                date: newDate,\n            });\n            return;\n        }\n        setCustom({\n            view: WEEK,\n            range: resetRange ? undefined : numberOfDays,\n            date: newDate,\n        });\n    }, []);\n\n    const handleClickDateWeekView = useCallback((newDate: Date) => {\n        if (newDate < MINIMUM_DATE_UTC || newDate > MAXIMUM_DATE_UTC) {\n            return;\n        }\n        setCustom({ view: DAY, range: undefined, date: newDate });\n    }, []);\n\n    const [defaultCalendarBootstrap, loadingCalendarBootstrap] = useCalendarBootstrap(\n        defaultCalendar ? defaultCalendar.ID : undefined\n    );\n\n    const [containerRef, setContainerRef] = useState<HTMLDivElement | null>(null);\n\n    const isLoading = loadingCalendarBootstrap || loadingEvents;\n    const isEventCreationDisabled =\n        disableCreate || !defaultCalendarBootstrap || !activeCalendars.some(unary(getIsCalendarWritable));\n\n    return (\n        <CalendarContainerView\n            calendarUserSettings={calendarUserSettings}\n            calendars={calendars}\n            onCreateCalendarFromSidebar={(id: string) => setInitializeCacheOnlyCalendarsIDs([id])}\n            isLoading={isLoading}\n            displayWeekNumbers={displayWeekNumbers}\n            weekStartsOn={weekStartsOn}\n            tzid={tzid}\n            setTzid={setCustomTzid}\n            range={range}\n            view={view}\n            isNarrow={isNarrow}\n            utcDateRangeInTimezone={utcDateRangeInTimezone}\n            utcDefaultDate={utcDefaultDate}\n            utcDate={utcDate}\n            utcDateRange={utcDateRange}\n            onCreateEvent={\n                isEventCreationDisabled\n                    ? undefined\n                    : (attendees: AttendeeModel[] = []) => interactiveRef.current?.createEvent(attendees)\n            }\n            onClickToday={handleClickToday}\n            onChangeDate={handleChangeDate}\n            onChangeDateRange={handleChangeDateRange}\n            onChangeView={handleChangeView}\n            containerRef={setContainerRef}\n            addresses={addresses}\n        >\n            {!!localTimezoneId && (\n                <AskUpdateTimezoneModal\n                    isOpen={isAskUpdateTimezoneModalOpen}\n                    onClose={() => setIsAskUpdateTimezoneModalOpen(false)}\n                    localTzid={localTimezoneId}\n                />\n            )}\n            {renderShareCalendarInvitationModal && shareCalendarInvitation && (\n                <ShareCalendarInvitationModal\n                    {...shareCalendarInvitationModal}\n                    addresses={addresses}\n                    calendars={calendars}\n                    user={user}\n                    invitation={shareCalendarInvitation}\n                />\n            )}\n\n            <InteractiveCalendarView\n                view={view}\n                isNarrow={isNarrow}\n                isLoading={isLoading}\n                tzid={tzid}\n                {...timezoneInformation}\n                displayWeekNumbers={displayWeekNumbers}\n                displaySecondaryTimezone={displaySecondaryTimezone}\n                weekStartsOn={weekStartsOn}\n                inviteLocale={inviteLocale}\n                now={utcNowDateInTimezone}\n                date={utcDate}\n                dateRange={utcDateRange}\n                events={calendarsEvents}\n                onClickDate={isNarrow ? handleChangeDate : handleClickDateWeekView}\n                onChangeDate={handleChangeDate}\n                onClickToday={handleClickToday}\n                isEventCreationDisabled={isEventCreationDisabled}\n                onInteraction={(active: boolean) => setDisableCreate(active)}\n                calendars={calendars}\n                addresses={addresses}\n                activeAddresses={activeAddresses}\n                activeCalendars={activeCalendars}\n                defaultCalendar={defaultCalendar}\n                defaultCalendarBootstrap={defaultCalendarBootstrap}\n                interactiveRef={interactiveRef}\n                containerRef={containerRef}\n                timeGridViewRef={timeGridViewRef}\n                calendarsEventsCacheRef={calendarsEventsCacheRef}\n                eventTargetActionRef={eventTargetActionRef}\n                getOpenedMailEvents={getOpenedMailEvents}\n            />\n        </CalendarContainerView>\n    );\n};\n\nexport default CalendarContainer;\n","import { useEffect, useState } from 'react';\n\nimport { DAY } from '@proton/shared/lib/constants';\n\nimport { useFeature } from '../../hooks';\nimport { FeatureCode } from '../features';\nimport useHasRebrandingFeedback from './useHasRebrandingFeedback';\n\nexport interface RebrandingFeatureValue {\n    /* User has visited rebranding in the past */\n    visited: boolean;\n    /* User has given rebranding feedback */\n    completed: boolean;\n    /* User has been prompted for rebranding feedback in the past */\n    prompted: boolean;\n}\n\n/*\n * Need to make sure that the functionality inside of the useEffect below really only runs once per runtime of\n * the application independently of what happens in the react tree. After the useEffect has ran once, we don't\n * ever want to run it again in the same runtime.\n */\nlet logicAlreadyRanDuringCurrentRuntime = false;\n\nconst useRebrandingFeedback = () => {\n    const hasRebrandingFeedback = useHasRebrandingFeedback();\n    const rebranding = useFeature<RebrandingFeatureValue>(FeatureCode.RebrandingFeedback);\n\n    const [handleDisplay, setHandleDisplay] = useState<undefined | (() => void)>(undefined);\n\n    useEffect(() => {\n        if (\n            rebranding.loading ||\n            !rebranding.feature?.Value ||\n            logicAlreadyRanDuringCurrentRuntime ||\n            !hasRebrandingFeedback\n        ) {\n            return;\n        }\n\n        /**\n         * Features are assumed to be loaded at this point, as ensured by the conditions above.\n         * This is important because this logic is only supposed to run once ever, therefore the\n         * data it consumes needs to be guaranteed in advance.\n         */\n        logicAlreadyRanDuringCurrentRuntime = true;\n\n        let promptTimeoutId: undefined | number;\n\n        const { Value: rebrandingValue } = rebranding.feature;\n\n        const updateRebranding = (value: Partial<RebrandingFeatureValue>) => {\n            void rebranding.update({ ...rebrandingValue, ...value });\n        };\n\n        const { visited, completed, prompted } = rebrandingValue;\n\n        const prompt = () => {\n            /**\n             * User has already visited the v5 / rebranding update AND has already been\n             * prompted for feedback previously. So we don't ask again.\n             */\n            if (prompted) {\n                return;\n            }\n\n            /* We didn't prompt the user but they already gave feedback on their own */\n            if (completed) {\n                return;\n            }\n\n            /*\n             * We want to store the \"handleDisplay\" callback here, not use react's\n             * setState callback api, therefore the curry. Yum!\n             */\n            setHandleDisplay(() => () => {\n                updateRebranding({ prompted: true });\n            });\n        };\n\n        /**\n         * User is visiting v5 / rebranding for the first time, we register this so\n         * that we can prompt them the next time they visit again.\n         *\n         * Alternatively, we also schedule a timer should the user not refresh / close\n         * his browser for a really long time, prompting him anyway after expiration of\n         * a certain amount of time in that case.\n         */\n        if (!visited) {\n            updateRebranding({ visited: true });\n\n            promptTimeoutId = window.setTimeout(prompt, DAY);\n\n            return;\n        }\n\n        prompt();\n\n        return () => {\n            window.clearTimeout(promptTimeoutId);\n        };\n    }, [rebranding.loading, rebranding, hasRebrandingFeedback]);\n\n    return handleDisplay;\n};\n\nexport default useRebrandingFeedback;\n","import { Dispatch, SetStateAction, useEffect, useRef } from 'react';\n\nimport {\n    FeatureCode,\n    RebrandingFeedbackModal,\n    getShouldOpenReferralModal,\n    useFeature,\n    useModalState,\n    useRebrandingFeedback,\n    useSubscription,\n} from '@proton/components';\nimport { OPEN_OFFER_MODAL_EVENT } from '@proton/shared/lib/constants';\n\ninterface Props {\n    setStartupModalState: Dispatch<SetStateAction<{ hasModal?: boolean; isOpen: boolean }>>;\n}\n\nconst CalendarStartupModals = ({ setStartupModalState }: Props) => {\n    // Referral modal\n    const [subscription] = useSubscription();\n    const seenReferralModal = useFeature<boolean>(FeatureCode.SeenReferralModal);\n    const shouldOpenReferralModal = getShouldOpenReferralModal({ subscription, feature: seenReferralModal.feature });\n\n    const [rebrandingFeedbackModal, setRebrandingFeedbackModal, renderRebrandingFeedbackModal] = useModalState();\n    const handleRebrandingFeedbackModalDisplay = useRebrandingFeedback();\n\n    const onCloseWithState = (onClose: () => void) => () => {\n        onClose();\n        setStartupModalState((state) => ({ ...state, isOpen: false }));\n    };\n\n    const onceRef = useRef(false);\n    useEffect(() => {\n        if (onceRef.current) {\n            return;\n        }\n\n        const openModal = (setModalOpen: (newValue: boolean) => void) => {\n            onceRef.current = true;\n            setModalOpen(true);\n            setStartupModalState({ hasModal: true, isOpen: true });\n        };\n\n        if (shouldOpenReferralModal.open) {\n            onceRef.current = true;\n            setStartupModalState({ hasModal: true, isOpen: true });\n            document.dispatchEvent(new CustomEvent(OPEN_OFFER_MODAL_EVENT));\n        } else if (handleRebrandingFeedbackModalDisplay) {\n            openModal(setRebrandingFeedbackModal);\n        } else {\n            setStartupModalState({ hasModal: false, isOpen: false });\n        }\n    }, [shouldOpenReferralModal.open, handleRebrandingFeedbackModalDisplay]);\n\n    return (\n        <>\n            {renderRebrandingFeedbackModal && (\n                <RebrandingFeedbackModal\n                    onMount={handleRebrandingFeedbackModalDisplay}\n                    {...rebrandingFeedbackModal}\n                    onClose={onCloseWithState(rebrandingFeedbackModal.onClose)}\n                />\n            )}\n        </>\n    );\n};\n\nexport default CalendarStartupModals;\n","import { addDays, fromUnixTime, subDays } from 'date-fns';\n\nimport { isTrial } from '@proton/shared/lib/helpers/subscription';\nimport { Subscription } from '@proton/shared/lib/interfaces';\n\nimport { Feature } from '../../features';\n\nexport const getShouldOpenReferralModal = ({\n    subscription,\n    feature,\n}: {\n    subscription: Subscription | undefined;\n    feature: Feature<boolean> | undefined;\n}) => {\n    if (!subscription?.PeriodEnd || !isTrial(subscription)) {\n        return { open: false, endDate: new Date() };\n    }\n\n    const endDate = fromUnixTime(subscription.PeriodEnd);\n    const startDate = fromUnixTime(subscription.CreateTime);\n    const nowDate = new Date();\n    // Should be in trial since a week\n    const isExperienced = addDays(startDate, 7) < nowDate;\n    // 3 days before the end of the trial\n    const willExpire = subDays(endDate, 3) < nowDate;\n    const open = (isExperienced && feature?.Value === false) || willExpire;\n\n    return { open, endDate };\n};\n","import { MutableRefObject, useEffect } from 'react';\nimport { useHistory } from 'react-router-dom';\n\nimport { c } from 'ttag';\n\nimport { LoaderPage, useNotifications } from '@proton/components';\nimport { ACTION_VIEWS, VIEWS } from '@proton/shared/lib/calendar/constants';\nimport { getDateOrDateTimeProperty, propertyToUTCDate } from '@proton/shared/lib/calendar/vcalConverter';\nimport { convertUTCDateTimeToZone, fromUTCDate, toUTCDate } from '@proton/shared/lib/date/timezone';\nimport { Address } from '@proton/shared/lib/interfaces';\nimport { CalendarEvent, VisualCalendar } from '@proton/shared/lib/interfaces/calendar';\nimport { VcalVeventComponent } from '@proton/shared/lib/interfaces/calendar/VcalModel';\n\nimport { useOpenEvent } from '../../hooks/useOpenEvent';\nimport { getCalendarEventStoreRecord } from './eventStore/cache/upsertCalendarEventStoreRecord';\nimport { VIEW_URL_PARAMS_VIEWS_CONVERSION } from './getUrlHelper';\nimport { EventTargetAction } from './interface';\n\nconst { VIEW } = ACTION_VIEWS;\n\ninterface Props {\n    addresses: Address[];\n    calendars: VisualCalendar[];\n    drawerView?: VIEWS;\n    tzid: string;\n    eventTargetActionRef: MutableRefObject<EventTargetAction | undefined>;\n}\nconst EventActionContainer = ({ tzid, drawerView, addresses, calendars, eventTargetActionRef }: Props) => {\n    const { createNotification } = useNotifications();\n    const history = useHistory();\n    const openEvent = useOpenEvent();\n\n    useEffect(() => {\n        const run = async () => {\n            const params = new URLSearchParams(window.location.search);\n            const action = params.get('Action');\n            const possiblyDrawerView = drawerView ? `/${VIEW_URL_PARAMS_VIEWS_CONVERSION[drawerView]}` : '';\n\n            if (action === VIEW) {\n                const handleLinkError = () => {\n                    createNotification({\n                        type: 'error',\n                        text: c('Error').t`Invalid link to the event`,\n                    });\n                    history.replace(`${possiblyDrawerView}/`);\n                };\n\n                const handleOtherError = () => {\n                    history.replace(`${possiblyDrawerView}/`);\n                };\n\n                const handleGotoRange = (date: Date) => {\n                    const viewString = drawerView ? possiblyDrawerView : '/week';\n                    history.replace(\n                        `${viewString}/${[date.getUTCFullYear(), date.getUTCMonth() + 1, date.getUTCDate()].join('/')}`\n                    );\n                };\n\n                const handleGotoOccurrence = (\n                    eventData: CalendarEvent,\n                    eventComponent: VcalVeventComponent,\n                    occurrence: { localStart: Date; occurrenceNumber: number }\n                ) => {\n                    const { isAllDay, isAllPartDay } = getCalendarEventStoreRecord(eventComponent, eventData);\n\n                    const withOccurrenceDtstart = getDateOrDateTimeProperty(\n                        eventComponent.dtstart,\n                        occurrence.localStart\n                    );\n                    const utcDate = propertyToUTCDate(withOccurrenceDtstart);\n                    const startInTzid = toUTCDate(convertUTCDateTimeToZone(fromUTCDate(utcDate), tzid));\n                    eventTargetActionRef.current = {\n                        id: `${eventData.ID}-${occurrence.occurrenceNumber}`,\n                        isAllDay,\n                        isAllPartDay,\n                        startInTzid,\n                        preventPopover: !!drawerView, // If the app is a drawer app, we want to prevent the popover opening\n                    };\n                    return handleGotoRange(startInTzid);\n                };\n\n                const handleGotoEvent = (eventData: CalendarEvent, eventComponent: VcalVeventComponent) => {\n                    const { isAllDay, isAllPartDay } = getCalendarEventStoreRecord(eventComponent, eventData);\n\n                    const utcDate = propertyToUTCDate(eventComponent.dtstart);\n                    const startInTzid = toUTCDate(convertUTCDateTimeToZone(fromUTCDate(utcDate), tzid));\n                    eventTargetActionRef.current = {\n                        id: eventData.ID,\n                        isAllDay,\n                        isAllPartDay,\n                        startInTzid,\n                        preventPopover: !!drawerView, // If the app is a drawer app, we want to prevent the popover opening\n                    };\n                    return handleGotoRange(startInTzid);\n                };\n\n                const calendarID = params.get('CalendarID');\n                const eventID = params.get('EventID');\n                const recurrenceId = params.get('RecurrenceID');\n\n                const openedEvent = await openEvent({\n                    calendars,\n                    addresses,\n                    calendarID,\n                    eventID,\n                    recurrenceId,\n                    onGoToEvent: handleGotoEvent,\n                    onGoToOccurrence: handleGotoOccurrence,\n                    onLinkError: handleLinkError,\n                    onOtherError: handleOtherError,\n                });\n\n                return openedEvent;\n            }\n\n            history.replace('');\n        };\n\n        void run();\n    }, []);\n\n    return <LoaderPage />;\n};\n\nexport default EventActionContainer;\n","import { MutableRefObject, useEffect } from 'react';\nimport { useHistory } from 'react-router-dom';\n\ninterface Props {\n    shareCalendarInvitationRef: MutableRefObject<{ calendarID: string; invitationID: string } | undefined>;\n}\n\nconst ShareInvitationContainer = ({ shareCalendarInvitationRef }: Props) => {\n    const history = useHistory();\n\n    useEffect(() => {\n        const urlParams = new URLSearchParams(window.location.search);\n        const calendarID = urlParams.get('CalendarID');\n        const invitationID = urlParams.get('InvitationID');\n\n        if (calendarID && invitationID) {\n            shareCalendarInvitationRef.current = { calendarID, invitationID };\n        }\n        history.replace('/');\n    }, []);\n\n    return null;\n};\n\nexport default ShareInvitationContainer;\n","import { CalendarEventsCache, CalendarsEventsCache } from '../interface';\nimport { getIsCalendarEvent } from './helper';\n\nconst getCalendarsEventCache = (): CalendarsEventsCache => {\n    const calendarsCache: { [key: string]: CalendarEventsCache } = {};\n\n    const getCachedEvent = (calendarID: string, eventID: string) => {\n        const calendarCache = calendarsCache[calendarID];\n        if (!calendarCache) {\n            return;\n        }\n        const cachedEvent = calendarCache.events.get(eventID);\n        const eventData = cachedEvent?.eventData;\n        return eventData && getIsCalendarEvent(eventData) ? eventData : undefined;\n    };\n\n    const getCachedRecurringEvent = (calendarID: string, uid: string) => {\n        const calendarCache = calendarsCache[calendarID];\n        if (!calendarCache) {\n            return;\n        }\n        return calendarCache.recurringEvents.get(uid);\n    };\n\n    const retryReadEvent = async (calendarID: string, eventID: string) => {\n        const calendarCache = calendarsCache[calendarID];\n\n        return calendarCache?.events.get(eventID)?.eventReadRetry?.();\n    };\n\n    const ref = 0;\n    const isUnmounted = false;\n\n    return {\n        ref,\n        isUnmounted,\n        calendars: calendarsCache,\n        getCachedEvent,\n        getCachedRecurringEvent,\n        retryReadEvent,\n    };\n};\n\nexport default getCalendarsEventCache;\n","import { fromUnixTime } from 'date-fns';\n\nimport { toExdate } from '@proton/shared/lib/calendar/exdate';\nimport getRecurrenceIdValueFromTimestamp from '@proton/shared/lib/calendar/recurrence/getRecurrenceIdValueFromTimestamp';\nimport { fromRruleString } from '@proton/shared/lib/calendar/vcal';\nimport { getDateProperty, getDateTimeProperty } from '@proton/shared/lib/calendar/vcalConverter';\nimport { SECOND } from '@proton/shared/lib/constants';\nimport { convertTimestampToTimezone, fromUTCDate } from '@proton/shared/lib/date/timezone';\nimport { Nullable } from '@proton/shared/lib/interfaces';\nimport { CalendarEventWithoutBlob } from '@proton/shared/lib/interfaces/calendar';\nimport { VcalRrulePropertyValue } from '@proton/shared/lib/interfaces/calendar/VcalModel';\n\nimport { MetadataVcalVeventComponent } from '../interface';\n\nconst getComponentFromCalendarEventWithoutBlob = (eventData: CalendarEventWithoutBlob): MetadataVcalVeventComponent => {\n    const { FullDay, StartTime, StartTimezone, EndTime, EndTimezone, RRule, RecurrenceID, Exdates } = eventData;\n    const isAllDay = FullDay === 1;\n\n    const getDtstampComponent = () => {\n        return {\n            dtstamp: { value: { ...fromUTCDate(new Date()), isUTC: true } },\n        };\n    };\n\n    const getTimeComponents = () => {\n        if (isAllDay) {\n            const utcStartDate = fromUnixTime(StartTime);\n            const utcEndDate = fromUnixTime(EndTime);\n            return {\n                dtstart: getDateProperty(fromUTCDate(utcStartDate)),\n                dtend: getDateProperty(fromUTCDate(utcEndDate)),\n            };\n        }\n        const localStartDateTime = convertTimestampToTimezone(StartTime * SECOND, StartTimezone);\n        const localEndDateTime = convertTimestampToTimezone(EndTime * SECOND, EndTimezone);\n        return {\n            dtstart: getDateTimeProperty(localStartDateTime, StartTimezone),\n            dtend: getDateTimeProperty(localEndDateTime, EndTimezone),\n        };\n    };\n\n    const getRruleComponent = (Rrule: Nullable<string>) => {\n        if (!Rrule) {\n            return {};\n        }\n        const rruleValue: VcalRrulePropertyValue | undefined = fromRruleString(Rrule);\n        if (!rruleValue) {\n            return {};\n        }\n        return { rrule: { value: rruleValue } };\n    };\n\n    const getRecurrenceIdComponent = (recurrenceId: Nullable<number>) => {\n        if (!recurrenceId) {\n            return {};\n        }\n        return {\n            'recurrence-id': getRecurrenceIdValueFromTimestamp(recurrenceId, isAllDay, StartTimezone),\n        };\n    };\n\n    const getRecurrenceExdate = (exdates: number[]) => {\n        if (!Array.isArray(exdates) || exdates.length === 0) {\n            return;\n        }\n        return {\n            exdate: exdates.map((exdate) => {\n                return toExdate(convertTimestampToTimezone(exdate * SECOND, StartTimezone), isAllDay, StartTimezone);\n            }),\n        };\n    };\n\n    return {\n        component: 'vevent',\n        uid: {\n            value: eventData.UID,\n        },\n        ...getDtstampComponent(),\n        ...getTimeComponents(),\n        ...getRruleComponent(RRule),\n        ...getRecurrenceIdComponent(RecurrenceID),\n        ...getRecurrenceExdate(Exdates),\n    };\n};\n\nexport default getComponentFromCalendarEventWithoutBlob;\n","import { pick } from '@proton/shared/lib/helpers/object';\nimport { CalendarEventWithoutBlob } from '@proton/shared/lib/interfaces/calendar';\n\nimport { CalendarEventsCache } from '../interface';\nimport getComponentFromCalendarEventWithoutBlob from './getComponentFromCalendarEventWithoutBlob';\nimport removeCalendarEventStoreRecord from './removeCalendarEventStoreRecord';\nimport { getCalendarEventStoreRecord, upsertCalendarEventStoreRecord } from './upsertCalendarEventStoreRecord';\n\nconst FIELDS_TO_KEEP = [\n    'ID',\n    'Author',\n    'SharedEventID',\n    'CalendarID',\n    'CreateTime',\n    'ModifyTime',\n    'Permissions',\n    'IsOrganizer',\n    'IsProtonProtonInvite',\n    'IsPersonalMigrated',\n] as const;\n\nconst upsertCalendarApiEventWithoutBlob = (\n    Event: CalendarEventWithoutBlob,\n    calendarEventsCache: CalendarEventsCache\n) => {\n    const eventID = Event.ID;\n    try {\n        const eventComponent = getComponentFromCalendarEventWithoutBlob(Event);\n        const eventData = pick(Event, FIELDS_TO_KEEP);\n        const newCalendarEventStoreRecord = getCalendarEventStoreRecord(eventComponent, eventData);\n        return upsertCalendarEventStoreRecord(eventID, newCalendarEventStoreRecord, calendarEventsCache);\n    } catch {\n        removeCalendarEventStoreRecord(eventID, calendarEventsCache);\n        return false;\n    }\n};\n\nexport default upsertCalendarApiEventWithoutBlob;\n","import { MutableRefObject, useEffect } from 'react';\n\nimport { useCalendarModelEventManager, useEventManager } from '@proton/components';\nimport { EVENT_ACTIONS } from '@proton/shared/lib/constants';\nimport { CalendarEventManager, CalendarEventsEventManager } from '@proton/shared/lib/interfaces/calendar/EventManager';\n\nimport { OpenedMailEvent } from '../../../hooks/useGetOpenedMailEvents';\nimport removeCalendarEventStoreRecord from './cache/removeCalendarEventStoreRecord';\nimport upsertCalendarApiEventWithoutBlob from './cache/upsertCalendarApiEventWithoutBlobs';\nimport { CalendarsEventsCache } from './interface';\n\nexport const useCalendarCacheEventListener = (\n    cacheRef: MutableRefObject<CalendarsEventsCache>,\n    calendarIDs: string[],\n    getOpenedMailEvents: () => OpenedMailEvent[]\n) => {\n    const { subscribe: standardSubscribe } = useEventManager();\n    const { subscribe: calendarSubscribe } = useCalendarModelEventManager();\n\n    // subscribe to general event loop\n    useEffect(() => {\n        return standardSubscribe(({ Calendars = [] }: { Calendars?: CalendarEventManager[] }) => {\n            const cache = cacheRef.current;\n            if (!cache) {\n                return;\n            }\n            const { calendars } = cache;\n\n            let actions = 0;\n\n            Calendars.forEach(({ ID: CalendarID, Action }) => {\n                if (Action === EVENT_ACTIONS.DELETE) {\n                    delete calendars[CalendarID];\n                    actions++;\n                }\n            });\n\n            if (actions) {\n                cacheRef.current.rerender?.();\n            }\n        });\n    }, []);\n\n    // subscribe to calendar event loop\n    useEffect(() => {\n        return calendarSubscribe(\n            calendarIDs,\n            ({ CalendarEvents = [] }: { CalendarEvents?: CalendarEventsEventManager[] }) => {\n                const cache = cacheRef.current;\n                if (!cache) {\n                    return;\n                }\n                const { calendars } = cache;\n\n                let actions = 0;\n\n                CalendarEvents.forEach((CalendarEventsChange) => {\n                    if (CalendarEventsChange.Action === EVENT_ACTIONS.DELETE) {\n                        // The API does not send the calendar id to which this event belongs, so find it\n                        const calendarID = Object.keys(calendars).find((calendarID) => {\n                            return calendars[calendarID]?.events.has(CalendarEventsChange.ID);\n                        });\n                        const calendarsEventsCache = calendars[calendarID || 'undefined'];\n                        if (!calendarsEventsCache) {\n                            return;\n                        }\n                        removeCalendarEventStoreRecord(\n                            CalendarEventsChange.ID,\n                            calendarsEventsCache,\n                            getOpenedMailEvents\n                        );\n                        // TODO: Only increment count if this event happened in the date range we are currently interested in\n                        actions++;\n                    }\n\n                    if (\n                        CalendarEventsChange.Action === EVENT_ACTIONS.UPDATE ||\n                        CalendarEventsChange.Action === EVENT_ACTIONS.CREATE\n                    ) {\n                        const { CalendarID } = CalendarEventsChange.Event;\n\n                        const calendarsEventsCache = calendars[CalendarID];\n                        if (!calendarsEventsCache) {\n                            return;\n                        }\n                        upsertCalendarApiEventWithoutBlob(CalendarEventsChange.Event, calendarsEventsCache);\n                        // TODO: Only increment count if this event happened in the date range we are currently interested in\n                        actions++;\n                    }\n                });\n\n                if (actions > 0) {\n                    cache.rerender?.();\n                }\n            }\n        );\n    }, [calendarIDs]);\n};\n\nexport default useCalendarCacheEventListener;\n","import { useMemo, useRef, useState } from 'react';\nimport { Redirect, Route, Switch } from 'react-router';\n\nimport {\n    useActiveBreakpoint,\n    useCalendarUserSettings,\n    useCalendarsInfoListener,\n    useUserSettings,\n} from '@proton/components';\nimport ContactEmailsProvider from '@proton/components/containers/contacts/ContactEmailsProvider';\nimport {\n    DEFAULT_CALENDAR_USER_SETTINGS,\n    getDefaultCalendar,\n    getProbablyActiveCalendars,\n} from '@proton/shared/lib/calendar/calendar';\nimport { VIEWS } from '@proton/shared/lib/calendar/constants';\nimport { getDefaultTzid } from '@proton/shared/lib/calendar/getSettings';\nimport { getTimezone } from '@proton/shared/lib/date/timezone';\nimport { getActiveAddresses } from '@proton/shared/lib/helpers/address';\nimport { Address, UserModel } from '@proton/shared/lib/interfaces';\nimport { VisualCalendar } from '@proton/shared/lib/interfaces/calendar';\n\nimport { useGetOpenedMailEvents } from '../../hooks/useGetOpenedMailEvents';\nimport AlarmContainer from '../alarms/AlarmContainer';\nimport { CalendarsAlarmsCache } from '../alarms/CacheInterface';\nimport useCalendarsAlarmsEventListeners from '../alarms/useCalendarAlarmsEventListener';\nimport { getCalendarsAlarmsCache } from '../alarms/useCalendarsAlarms';\nimport CalendarContainer from './CalendarContainer';\nimport CalendarStartupModals from './CalendarStartupModals';\nimport EventActionContainer from './EventActionContainer';\nimport ShareInvitationContainer from './ShareInvitationContainer';\nimport getCalendarsEventCache from './eventStore/cache/getCalendarsEventCache';\nimport { CalendarsEventsCache } from './eventStore/interface';\nimport useCalendarsEventsEventListener from './eventStore/useCalendarsEventsEventListener';\nimport { EventTargetAction } from './interface';\n\ninterface Props {\n    calendars: VisualCalendar[];\n    addresses: Address[];\n    user: UserModel;\n    drawerView?: VIEWS;\n}\n\nconst MainContainerSetup = ({ user, addresses, calendars, drawerView }: Props) => {\n    const { isNarrow } = useActiveBreakpoint();\n    const [userSettings] = useUserSettings();\n    const [calendarUserSettings = DEFAULT_CALENDAR_USER_SETTINGS] = useCalendarUserSettings();\n\n    const { activeCalendars, visibleCalendars, allCalendarIDs } = useMemo(() => {\n        return {\n            calendars,\n            activeCalendars: getProbablyActiveCalendars(calendars),\n            visibleCalendars: calendars.filter(({ Display }) => !!Display),\n            allCalendarIDs: calendars.map(({ ID }) => ID),\n        };\n    }, [calendars]);\n\n    useCalendarsInfoListener(allCalendarIDs);\n\n    const getOpenedMailEvents = useGetOpenedMailEvents(drawerView);\n    const calendarsEventsCacheRef = useRef<CalendarsEventsCache>(getCalendarsEventCache());\n    useCalendarsEventsEventListener(calendarsEventsCacheRef, allCalendarIDs, getOpenedMailEvents);\n\n    const calendarAlarmsCacheRef = useRef<CalendarsAlarmsCache>(getCalendarsAlarmsCache());\n    useCalendarsAlarmsEventListeners(calendarAlarmsCacheRef, allCalendarIDs);\n\n    const eventTargetActionRef = useRef<EventTargetAction>();\n    const shareCalendarInvitationRef = useRef<{ calendarID: string; invitationID: string }>();\n\n    const activeAddresses = useMemo(() => {\n        return getActiveAddresses(addresses);\n    }, [addresses]);\n\n    const defaultCalendar = getDefaultCalendar(activeCalendars, calendarUserSettings.DefaultCalendarID);\n\n    const [localTzid] = useState(() => getTimezone());\n    const [customTzid, setCustomTzid] = useState('');\n    const defaultTzid = getDefaultTzid(calendarUserSettings, localTzid);\n\n    // In the drawer the time zone selector won't be visible. We want to force using the browser time zone\n    // We have to do it here, so that we use the correct timezone in EventActionContainer and in CalendarContainer\n    const tzid = drawerView ? getTimezone() : customTzid || defaultTzid;\n\n    const [startupModalState, setStartupModalState] = useState<{ hasModal?: boolean; isOpen: boolean }>({\n        isOpen: false,\n    });\n\n    return (\n        <ContactEmailsProvider>\n            <CalendarStartupModals setStartupModalState={setStartupModalState} />\n            <Switch>\n                <Route path={['/:appName/event', '/event']}>\n                    <EventActionContainer\n                        drawerView={drawerView}\n                        tzid={tzid}\n                        addresses={addresses}\n                        calendars={calendars}\n                        eventTargetActionRef={eventTargetActionRef}\n                    />\n                </Route>\n                <Route path={'/share'}>\n                    <ShareInvitationContainer shareCalendarInvitationRef={shareCalendarInvitationRef} />\n                </Route>\n                <Route path=\"/\">\n                    <CalendarContainer\n                        tzid={tzid}\n                        setCustomTzid={setCustomTzid}\n                        isNarrow={isNarrow}\n                        drawerView={drawerView}\n                        user={user}\n                        addresses={addresses}\n                        activeAddresses={activeAddresses}\n                        visibleCalendars={visibleCalendars}\n                        activeCalendars={activeCalendars}\n                        calendars={calendars}\n                        defaultCalendar={defaultCalendar}\n                        calendarsEventsCacheRef={calendarsEventsCacheRef}\n                        calendarUserSettings={calendarUserSettings}\n                        userSettings={userSettings}\n                        eventTargetActionRef={eventTargetActionRef}\n                        shareCalendarInvitationRef={shareCalendarInvitationRef}\n                        startupModalState={startupModalState}\n                        getOpenedMailEvents={getOpenedMailEvents}\n                    />\n                </Route>\n                <Redirect to=\"/\" />\n            </Switch>\n            <AlarmContainer\n                calendars={visibleCalendars}\n                tzid={tzid}\n                calendarsEventsCacheRef={calendarsEventsCacheRef}\n                calendarsAlarmsCacheRef={calendarAlarmsCacheRef}\n            />\n        </ContactEmailsProvider>\n    );\n};\n\nexport default MainContainerSetup;\n","import { useMemo, useState } from 'react';\nimport { useLocation } from 'react-router-dom';\n\nimport {\n    ErrorBoundary,\n    FeatureCode,\n    StandardErrorPage,\n    useAddresses,\n    useCalendars,\n    useFeatures,\n    useUser,\n    useWelcomeFlags,\n} from '@proton/components';\nimport useTelemetryScreenSize from '@proton/components/hooks/useTelemetryScreenSize';\nimport { useInstance } from '@proton/hooks/index';\nimport { getOwnedPersonalCalendars, getVisualCalendars, sortCalendars } from '@proton/shared/lib/calendar/calendar';\nimport { CALENDAR_FLAGS } from '@proton/shared/lib/calendar/constants';\n\nimport Favicon from '../../components/Favicon';\nimport { getIsCalendarAppInDrawer } from '../../helpers/views';\nimport CalendarOnboardingContainer from '../setup/CalendarOnboardingContainer';\nimport CalendarSetupContainer from '../setup/CalendarSetupContainer';\nimport ResetContainer from '../setup/ResetContainer';\nimport MainContainerSetup from './MainContainerSetup';\nimport { fromUrlParams } from './getUrlHelper';\n\nconst MainContainer = () => {\n    useTelemetryScreenSize();\n\n    const [addresses] = useAddresses();\n    const [calendars] = useCalendars();\n    const [user] = useUser();\n    const { pathname } = useLocation();\n\n    const drawerView = useInstance(() => {\n        const { view } = fromUrlParams(pathname);\n        if (!getIsCalendarAppInDrawer(view)) {\n            return;\n        }\n        document.body.classList.add('is-drawer-app');\n\n        return view;\n    });\n\n    useFeatures([\n        FeatureCode.SpotlightSubscribedCalendars,\n        FeatureCode.CalendarSharingEnabled,\n        FeatureCode.CalendarPersonalEventsDeprecated,\n    ]);\n\n    const memoedCalendars = useMemo(() => sortCalendars(getVisualCalendars(calendars || [])), [calendars]);\n    const ownedPersonalCalendars = useMemo(() => getOwnedPersonalCalendars(memoedCalendars), [memoedCalendars]);\n    const memoedAddresses = useMemo(() => addresses || [], [addresses]);\n\n    const [welcomeFlags, setWelcomeFlagsDone] = useWelcomeFlags();\n\n    const [hasCalendarToGenerate, setHasCalendarToGenerate] = useState(() => {\n        return ownedPersonalCalendars.length === 0;\n    });\n\n    const [calendarsToReset, setCalendarsToReset] = useState(() => {\n        return memoedCalendars.filter(({ Flags }) => {\n            return (Flags & (CALENDAR_FLAGS.RESET_NEEDED | CALENDAR_FLAGS.UPDATE_PASSPHRASE)) > 0;\n        });\n    });\n\n    const [calendarsToSetup, setCalendarsToSetup] = useState(() => {\n        return memoedCalendars.filter(({ Flags }) => {\n            return (Flags & CALENDAR_FLAGS.INCOMPLETE_SETUP) > 0;\n        });\n    });\n\n    if (hasCalendarToGenerate) {\n        return <CalendarSetupContainer onDone={() => setHasCalendarToGenerate(false)} />;\n    }\n\n    if (calendarsToSetup.length) {\n        return <CalendarSetupContainer calendars={calendarsToSetup} onDone={() => setCalendarsToSetup([])} />;\n    }\n\n    if (!welcomeFlags.isDone) {\n        return <CalendarOnboardingContainer onDone={() => setWelcomeFlagsDone()} />;\n    }\n\n    if (calendarsToReset.length) {\n        return <ResetContainer calendars={calendarsToReset} onDone={() => setCalendarsToReset([])} />;\n    }\n\n    return (\n        <MainContainerSetup\n            user={user}\n            addresses={memoedAddresses}\n            calendars={memoedCalendars}\n            drawerView={drawerView}\n        />\n    );\n};\n\nconst WrappedMainContainer = () => {\n    return (\n        <ErrorBoundary component={<StandardErrorPage />}>\n            <Favicon />\n            <MainContainer />\n        </ErrorBoundary>\n    );\n};\n\nexport default WrappedMainContainer;\n","import { ElementType, ReactElement, forwardRef } from 'react';\n